}
function git(...args) {
  const r = spawnSync("git", args, {
    cwd: root,
    encoding: "utf8",
    windowsHide: true,
  });
  if (r.status !== 0) throw new Error("Git revision operation failed");
  return r.stdout.trim();
}
function run(step, command, args, options = {}) {
  const log = resolve(dir, "logs", `${Date.now()}-${step}.log`),
    fd = openSync(log, "w");
  const result = spawnSync(command, args, {
    cwd: root,
    windowsHide: true,
    stdio: ["ignore", fd, fd],
    ...options,
  });
  closeSync(fd);
  if (result.status !== 0)
    throw new Error(
      `${step} failed (exit ${result.status}); inspect private staging logs`,
    );
}
function docker(...args) {
  const r = spawnSync("docker", args, {
    cwd: root,
    encoding: "utf8",
    windowsHide: true,
  });
