    const pg = spawnSync(
      "docker",
      [
        "exec",
        "sprint1-stage-pg-20261015",
        "pg_isready",
        "-U",
        c.user,
        "-d",
        c.database,
      ],
      { stdio: "ignore", windowsHide: true },
    );
    if (
      pg.status === 0 &&
      docker("exec", "sprint1-stage-redis-20261015", "redis-cli", "ping") ===
