  const env = {
    ...process.env,
    DATABASE_URL: dbURL,
    REDIS_HOST: "127.0.0.1",
    REDIS_PORT: String(c.redisPort),
    REDIS_URL: "",
    SPRINT1_STAGING_CONFIG: resolve(dir, "config.json"),
    SPRINT1_STAGING_WRITE: c.profile,
  };
